//! Thumbnails of the extracted images (task P3.6, ADR-016): PNG files generated by us, the only
//! image content the webview ever displays (never the original object).
//!
//! - Decoding: crate `image`, pure Rust codecs only (PNG, JPEG, GIF, WebP, BMP, ICO; first frame
//!   of animations). SVG is never rasterized. The format comes from the magic number, never
//!   from a declared type.
//! - Bounds: input at most [`MAX_INPUT_BYTES`]; `image::Limits` refuse an image wider or taller
//!   than [`MAX_DIMENSION`] or needing more than [`MAX_DECODE_ALLOC`] bytes **before** any pixel
//!   buffer is allocated (a 100000x100000 header costs nothing), which also bounds the work of
//!   a decompression bomb; decoding time is then proportional to at most that many pixels.
//!   A panic of a codec on hostile data is caught and reported as a failure.
//! - When: [`generate_pending`] runs once at the end of the import, after the writer and its
//!   end-of-import steps (which build `objects`), never in a shard: decoding costs much more
//!   than parsing. It uses a few threads, stops on cancellation and after a time limit; what is
//!   left stays `pending` and is rendered on demand by the API ([`render`], not cached).

use std::io::Cursor;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;
use std::time::{Duration, Instant};

use image::{DynamicImage, ImageFormat, ImageReader, Limits};
use netsift_store::objects::{self, PendingThumb, ThumbUpdate, thumb};
use netsift_store::session::{blob_relpath, thumb_relpath};
use netsift_store::{OpenMode, Session, StoreError};

use crate::options::CancelToken;

/// Longest side of a stored thumbnail, in pixels (tiles of the grid, on high-density screens).
pub const THUMB_SIZE: u32 = 320;
/// Longest side of the preview shown by the viewer, in pixels (rendered on demand).
pub const PREVIEW_SIZE: u32 = 1600;
/// Largest object decoded, in bytes (the HTTP analyzer stores nothing larger by default).
pub const MAX_INPUT_BYTES: usize = 16 * 1024 * 1024;
/// Largest width or height decoded, in pixels.
pub const MAX_DIMENSION: u32 = 16_384;
/// Largest allocation of a decoder, in bytes.
pub const MAX_DECODE_ALLOC: u64 = 128 * 1024 * 1024;
/// Time given to the end-of-import pass.
pub const PASS_TIME_LIMIT: Duration = Duration::from_secs(60);
/// Decoding threads of the end-of-import pass.
const MAX_WORKERS: usize = 4;

/// Why an image has no thumbnail.
#[derive(Debug, thiserror::Error, PartialEq, Eq)]
#[non_exhaustive]
pub enum ThumbError {
    #[error("object too large to decode")]
    TooLarge,
    #[error("not a supported raster image")]
    Unsupported,
    #[error("cannot decode the image: {0}")]
    Decode(String),
    #[error("cannot encode the thumbnail: {0}")]
    Encode(String),
    #[error("the decoder panicked")]
    Panicked,
}

/// A PNG rendition of an image.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rendered {
    pub png: Vec<u8>,
    /// Dimensions of the original image.
    pub width: u32,
    pub height: u32,
}

/// Decodes `data` within the limits and re-encodes it as a PNG whose longest side is at most
/// `max_side` (never enlarged). Never panics.
pub fn render(data: &[u8], max_side: u32) -> Result<Rendered, ThumbError> {
    if data.len() > MAX_INPUT_BYTES {
        return Err(ThumbError::TooLarge);
    }
    catch_unwind(AssertUnwindSafe(|| render_unguarded(data, max_side)))
        .unwrap_or(Err(ThumbError::Panicked))
}

fn render_unguarded(data: &[u8], max_side: u32) -> Result<Rendered, ThumbError> {
    let format = image::guess_format(data).map_err(|_| ThumbError::Unsupported)?;
    if !matches!(
        format,
        ImageFormat::Png
            | ImageFormat::Jpeg
            | ImageFormat::Gif
            | ImageFormat::WebP
            | ImageFormat::Bmp
            | ImageFormat::Ico
    ) {
        return Err(ThumbError::Unsupported);
    }
    let mut reader = ImageReader::with_format(Cursor::new(data), format);
    let mut limits = Limits::default();
    limits.max_image_width = Some(MAX_DIMENSION);
    limits.max_image_height = Some(MAX_DIMENSION);
    limits.max_alloc = Some(MAX_DECODE_ALLOC);
    reader.limits(limits);
    let image = reader
        .decode()
        .map_err(|e| ThumbError::Decode(e.to_string()))?;
    let (width, height) = (image.width(), image.height());
    let side = max_side.max(1);
    let small = if width > side || height > side {
        image.thumbnail(side, side)
    } else {
        image
    };
    // 8-bit RGB(A): what every webview displays, whatever the source depth.
    let out = if small.color().has_alpha() {
        DynamicImage::ImageRgba8(small.into_rgba8())
    } else {
        DynamicImage::ImageRgb8(small.into_rgb8())
    };
    let mut png = Vec::new();
    out.write_to(&mut Cursor::new(&mut png), ImageFormat::Png)
        .map_err(|e| ThumbError::Encode(e.to_string()))?;
    Ok(Rendered { png, width, height })
}

/// What [`generate_pending`] did.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ThumbReport {
    pub ready: usize,
    pub failed: usize,
    /// Still `pending` (cancelled, time limit, thumbnail not writable).
    pub left: usize,
}

/// Generates the missing thumbnails of a session (`objects.thumb = 'pending'`), writes them to
/// `thumbs/<aa>/<sha256>.png` and records the outcome with the image dimensions.
pub fn generate_pending(
    session_dir: &Path,
    cancel: &CancelToken,
    time_limit: Duration,
) -> Result<ThumbReport, StoreError> {
    let mut session = Session::open(session_dir, OpenMode::ReadWrite)?;
    let pending = objects::pending_thumbs(session.conn())?;
    if pending.is_empty() {
        return Ok(ThumbReport::default());
    }
    let dirs = Dirs {
        blobs: session.blobs_dir(),
        thumbs: session.thumbs_dir(),
    };
    let deadline = Instant::now() + time_limit;
    let next = AtomicUsize::new(0);
    let updates = Mutex::new(Vec::with_capacity(pending.len()));
    let workers = thread::available_parallelism()
        .map_or(1, std::num::NonZero::get)
        .clamp(1, MAX_WORKERS)
        .min(pending.len());
    thread::scope(|s| {
        for _ in 0..workers {
            s.spawn(|| {
                while !cancel.is_cancelled() && Instant::now() < deadline {
                    let Some(item) = pending.get(next.fetch_add(1, Ordering::Relaxed)) else {
                        break;
                    };
                    if let Some(update) = dirs.process(item)
                        && let Ok(mut all) = updates.lock()
                    {
                        all.push(update);
                    }
                }
            });
        }
    });
    let updates = updates.into_inner().unwrap_or_default();
    objects::set_thumbs(session.conn_mut(), &updates)?;
    let ready = updates.iter().filter(|u| u.state == thumb::READY).count();
    let failed = updates.len() - ready;
    Ok(ThumbReport {
        ready,
        failed,
        left: pending.len() - updates.len(),
    })
}

struct Dirs {
    blobs: PathBuf,
    thumbs: PathBuf,
}

impl Dirs {
    /// Thumbnail of one object; `None` leaves it pending (thumbnail not writable).
    fn process(&self, item: &PendingThumb) -> Option<ThumbUpdate> {
        let failed = || ThumbUpdate {
            sha256: item.sha256.clone(),
            state: thumb::FAILED,
            width: None,
            height: None,
        };
        let (Some(blob), Some(target)) = (
            blob_relpath(&item.sha256).map(|r| self.blobs.join(r)),
            thumb_relpath(&item.sha256).map(|r| self.thumbs.join(r)),
        ) else {
            return Some(failed());
        };
        let Some(data) = read_blob(&blob, item.size) else {
            return Some(failed());
        };
        let Ok(rendered) = render(&data, THUMB_SIZE) else {
            return Some(failed());
        };
        if let Err(e) = write_atomic(&target, &rendered.png) {
            tracing::warn!("cannot write a thumbnail: {e}");
            return None;
        }
        Some(ThumbUpdate {
            sha256: item.sha256.clone(),
            state: thumb::READY,
            width: Some(rendered.width),
            height: Some(rendered.height),
        })
    }
}

/// The blob, when it exists, has its recorded size and is small enough to decode.
pub fn read_blob(path: &Path, size: u64) -> Option<Vec<u8>> {
    let len = std::fs::metadata(path).ok()?.len();
    if len != size || usize::try_from(len).ok()? > MAX_INPUT_BYTES {
        return None;
    }
    let data = std::fs::read(path).ok()?;
    (u64::try_from(data.len()).ok()? == size).then_some(data)
}

fn write_atomic(path: &Path, data: &[u8]) -> std::io::Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| std::io::Error::from(std::io::ErrorKind::InvalidInput))?;
    std::fs::create_dir_all(parent)?;
    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let tmp = parent.join(format!(".{name}.{}.tmp", std::process::id()));
    if let Err(e) = std::fs::write(&tmp, data) {
        let _ = std::fs::remove_file(&tmp);
        return Err(e);
    }
    std::fs::rename(&tmp, path).inspect_err(|_| {
        let _ = std::fs::remove_file(&tmp);
    })
}

